    #sendFn;
    #options;
    #seq = 0;
    #opened = false;
    #ended = false;
    #endRequested = false;
    /** @type {Error|null} */
    #failure = null;
    #tail = Promise.resolve();
    #cancelled = deferred();
    /** @type {Promise<void>|null} */
    #endPromise = null;
    /** @type {StreamWindow|null} */
    #window = null;
    /** @type {ReturnType<typeof setTimeout>|null} */
    #timer = null;
    #abortListener = () => {
        void this.abort('Stream aborted by signal').catch(() => {});
