        const sid = message.sid;
        if (sid.length > 256) return;
        const outgoing = this.#outgoingStreams.get(sid);
        const active = this.#activeStreams.get(sid);
        if (message.st !== 'data') {
            try {
                assertPayloadSize(message, this.#options.maxControlBytes);
            } catch {
