        if ((message.st === 'ack' || message.st === 'error') && outgoing?.peerId === peerId) {
            outgoing.stream.handleMessage(message);
            return;
        }
        if (message.st === 'open' || message.st === 'open-flow') {
            if (active || outgoing || typeof message.name !== 'string') return;
